import { h, q, S, VIEWS, TERRAIN, GLYPH, terrainVar, terrain, table, riderCol, teamCol, baseOpt, axisStyle, chart, sweep, panel, seg, select, kv, sqlShow, open, live, tokens, natLink, fmtTime, fmtGap, fmtNum, shortTeam } from '../shared/core.js'

// ---------- Local helpers ----------
const day = (d) => new Date(`${d}T12:00:00`).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })
const arrow = (s) => (s.start_location === s.finish_location ? s.start_location : `${s.start_location} → ${s.finish_location}`)
const glyph = (t, size = 18) => h('span', { style: `color:${terrainVar(t)};display:inline-flex`, html: `<svg viewBox="0 0 20 14" width="${size}" height="${Math.round(size * 0.7)}" aria-hidden="true">${GLYPH[t]}</svg>` })
const ord = (n) => `${n}${n % 100 >= 11 && n % 100 <= 13 ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] ?? 'th'}`
const kmh = (v, d = 2) => fmtNum(v, d)
const signed = (v, d = 2) => `${v > 0 ? '+' : v < 0 ? '−' : ''}${fmtNum(Math.abs(v), d)}`
const redraw = (el) => { for (const e of live) if (e.el === el && e.inst) e.draw() }
// Places gained (▲) or lost (▼); the arrow and the number carry the meaning, the colour only repeats it.
const move = (d) => (d == null ? '' : d === 0 ? h('span', { class: 'dim' }, ' –') : h('span', { class: d > 0 ? 'up' : 'down' }, ` ${d > 0 ? '▲' : '▼'}${Math.abs(d)}`))
// A thin bar on a shared left baseline with its number at the end, for table cells.
const barCell = (v, max, text, colour) => h('span', { style: 'display:flex;align-items:center;gap:8px;min-width:110px' },
  h('span', { style: 'flex:1;height:8px;display:flex' }, h('span', { style: `width:${Math.max(1, (v / max) * 100)}%;background:${colour};border-radius:0 4px 4px 0` })),
  h('span', { class: 'mono', style: 'min-width:5ch;text-align:right;font-size:13px' }, text))

// ---------- Stage data: one row per stage ----------
const stagesSql = (extraCte = '', extraCol = '', extraJoin = '') => `WITH ${extraCte}yellow AS (   -- overall leader after each stage and the lead over the next rider
  SELECT p.stage_id, STRING_AGG(r.rider_name, ' / ' ORDER BY r.rider_name) AS leader, MIN(x.next_gap)::int AS lead_s
  FROM v_gc_progress p
  JOIN dim_rider r USING (rider_key)
  JOIN (SELECT stage_id, MIN(gap_to_leader) FILTER (WHERE gc_rank > 1) AS next_gap
        FROM v_gc_progress GROUP BY stage_id) x USING (stage_id)
  WHERE p.gc_rank = 1
  GROUP BY p.stage_id
), duel AS (   -- seconds the final winner gained on the final runner-up on each stage
  SELECT a.stage_key, (b.adjusted_time - a.adjusted_time)::int AS winner_gain
  FROM fact_results a
  JOIN fact_results b USING (stage_key)
  WHERE a.rider_key = (SELECT rider_key FROM v_gc WHERE gc_rank = 1)
    AND b.rider_key = (SELECT rider_key FROM v_gc WHERE gc_rank = 2)
)
SELECT s.stage_id, s.stage_date::text AS stage_date, s.terrain, s.distance_km::float8 AS km,
       s.start_location, s.finish_location,
       r.rider_key AS winner_key, r.rider_name AS winner, t.team_key AS winner_team_key, t.team_name AS winner_team,
       w.adjusted_time AS winner_time, w.speed_kmh::float8 AS winner_kmh,
       y.leader, y.lead_s, LAG(y.leader) OVER (ORDER BY s.stage_id) AS leader_before, d.winner_gain${extraCol}
FROM dim_stage s
JOIN fact_results w ON w.stage_key = s.stage_key AND w.is_win = 1
JOIN dim_rider r ON r.rider_key = w.rider_key
JOIN dim_team t ON t.team_key = w.team_key
JOIN yellow y ON y.stage_id = s.stage_id
JOIN duel d ON d.stage_key = s.stage_key${extraJoin}
ORDER BY s.stage_id;`

// Which stage the page opens on: 'lead' = the last change of the overall lead,
// 'gain' = the stage on which the final winner gained the most time on the runner-up.
const CFG = { focus: 'lead' }

async function loadRace(extraCte, extraCol, extraJoin) {
  const sql = stagesSql(extraCte, extraCol, extraJoin)
  const rows = await q(sql)
  const changes = rows.filter((r) => r.leader_before && r.leader_before !== r.leader)
  const settled = changes.at(-1) ?? rows[0]                                          // the last stage on which the overall lead changed hands
  const swing = rows.reduce((a, r) => (r.winner_gain > a.winner_gain ? r : a))       // the winner's largest gain on the runner-up
  return {
    sql, rows, settled, swing,
    decisive: CFG.focus === 'gain' ? swing : settled,
    margin: rows.reduce((a, r) => a + r.winner_gain, 0),
    longest: rows.reduce((a, r) => (r.km > a.km ? r : a)),
    get: (id) => rows.find((r) => r.stage_id === Number(id)),
  }
}

// ---------- Headline numbers ----------
function statRow(root, race) {
  const sum = (list) => list.reduce((a, r) => a + r.km, 0)
  const tile = (big, small) => h('div', {}, h('b', {}, big), h('span', {}, small))
  root.append(h('div', { class: 'stat' },
    tile(`${race.rows.length} stages`, `${day(race.rows[0].stage_date)} to ${day(race.rows.at(-1).stage_date)}`),
    tile(`${fmtNum(sum(race.rows), 1)} km`, 'total distance'),
    TERRAIN.map((t) => {
      const list = race.rows.filter((r) => r.terrain === t)
      return tile([glyph(t, 24), ` ${list.length} ${t}`], `${t === 'ITT' ? 'time trials · ' : ''}${fmtNum(sum(list) / list.length, 1)} km on average`)
    })))
}

const stageTip = (r) => `<b>Stage ${r.stage_id}</b> · ${day(r.stage_date)}<br>${arrow(r)}<br>${r.terrain} · ${fmtNum(r.km, 1)} km<br>Winner: ${r.winner}<br>Overall leader after: ${r.leader}`
