const note = (...kids) => h('div', { style: 'color:var(--ink);font-size:14px;margin:0 0 6px;max-width:110ch' }, ...kids)
const subhead = (text) => h('div', { style: 'font-weight:600;margin:0 0 4px' }, text)
// A line under a table that says how to read its columns.
const foot = (...kids) => h('div', { style: 'color:var(--ink);font-size:13px;margin:8px 0 0;max-width:110ch' }, ...kids)
// Where outside data comes from: grey, on its own line, each source a link.
