const cells = (runs) => {
  const out = []
  for (let i = 0; i < runs.length; i += 3) out.push([RELIEF.lon0 + runs[i + 1] * RELIEF.step, RELIEF.lat0 + runs[i] * RELIEF.step, runs[i + 2] * RELIEF.step])
  return out
}
const LAND_CELLS = cells(RELIEF.land), RELIEF_CELLS = RELIEF.runs.flatMap(cells)
// The coast comes from the terrain data. Of the rough outline of France only the land borders are kept:
// the stretches whose middle has no sea within about 20 km.
const LAND_BORDER = (() => {
  const dry = new Set()
  for (let i = 0; i < RELIEF.land.length; i += 3) for (let c = 0; c < RELIEF.land[i + 2]; c++) dry.add(`${RELIEF.land[i]},${RELIEF.land[i + 1] + c}`)
  const inland = ([lon, lat]) => {
    const row = Math.floor((lat - RELIEF.lat0) / RELIEF.step), col = Math.floor((lon - RELIEF.lon0) / RELIEF.step)
    for (let dr = -4; dr <= 4; dr++) for (let dc = -5; dc <= 5; dc++) if (!dry.has(`${row + dr},${col + dc}`)) return false
    return true
  }
  const ring = OUTLINE.find(([name]) => name === 'France')[1][0][0], out = []
  for (let i = 0; i + 1 < ring.length; i++) {
    const a = ring[i], b = ring[i + 1]
    if (inland([(a[0] + b[0]) / 2, (a[1] + b[1]) / 2])) out.push({ coords: [a, b] })
  }
  return out
})()

const cellRect = (fill, opacity) => (_, api) => {
  const a = api.coord([api.value(0), api.value(1) + RELIEF.step]), b = api.coord([api.value(0) + api.value(2), api.value(1)])
  const x = Math.round(a[0]), y = Math.round(a[1])
  return { type: 'rect', shape: { x, y, width: Math.round(b[0]) - x, height: Math.round(b[1]) - y }, style: { fill, opacity } }
}

// The route as a map. Stages up to state.n are drawn in the colour of their type, later stages in grey.
function routeMap(race, state, onPick, wide) {
  if (!echarts.getMap('tdf-route')) echarts.registerMap('tdf-route', { type: 'FeatureCollection',
    features: OUTLINE.map(([name, coordinates]) => ({ type: 'Feature', properties: { name }, geometry: { type: 'MultiPolygon', coordinates } })) })
  return chart((t) => {
    const done = (r) => r.stage_id <= state.n
    const on = (r) => r.stage_id === state.n
    const colour = (r) => (done(r) ? t.s[TERRAIN.indexOf(r.terrain)] : t.axis)
    const at = (r, end) => (end ? ROUTES[r.stage_id].at(-1) : ROUTES[r.stage_id][0])
    // stages still to come are drawn first, the chosen stage last, so the ridden route stays on top
    // in the replay (state.replay) a stage is only drawn once it has been ridden, and the two marks wait for the last stage
    const rows = [...race.rows].filter((r) => !state.replay || done(r)).sort((a, b) => (done(a) - done(b)) || (on(a) - on(b)))
    const marks = !state.replay || state.n >= race.rows.at(-1).stage_id
    return {
      ...baseOpt(t), legend: { show: false },
      animation: false,   // the marks are redrawn in a new order on every step; without this they would slide between towns
      tooltip: { ...baseOpt(t).tooltip, trigger: 'item', formatter: (x) => (x.data?.r ? stageTip(x.data.r) : '') },
      backgroundColor: t.surface,
      // the outline only sets the map frame; land, coast and terrain are drawn from the terrain data
      geo: { map: 'tdf-route', roam: false, silent: true, boundingCoords: [[-5.3, 51.3], [8.6, 42.2]], left: 0, right: 0, top: 0, bottom: 0, label: { show: false },
        itemStyle: { areaColor: 'transparent', borderWidth: 0 } },
      series: [
        // the sea as a light wash over the whole frame, then land, then terrain on top of it
        { type: 'custom', coordinateSystem: 'geo', silent: true, z: 0, data: [[2, 46.5, 0]],
          renderItem: (p) => ({ type: 'rect', shape: { x: 0, y: 0, width: p.coordSys.x * 2 + p.coordSys.width + 4000, height: 4000 }, style: { fill: t.s[0], opacity: 0.16 } }) },
        { type: 'custom', coordinateSystem: 'geo', silent: true, clip: true, z: 1, data: LAND_CELLS, renderItem: cellRect(t.surface, 1) },
        { type: 'custom', coordinateSystem: 'geo', silent: true, clip: true, z: 2, data: RELIEF_CELLS, renderItem: cellRect(t.ink, BAND) },
        { type: 'lines', coordinateSystem: 'geo', silent: true, z: 2, data: LAND_BORDER, lineStyle: { color: t.ink2, width: 1, opacity: 0.7, type: [4, 3] } },
        // the planned road of every stage
        { type: 'lines', coordinateSystem: 'geo', polyline: true, z: 3, lineStyle: { cap: 'round', join: 'round' }, emphasis: { lineStyle: { width: 5 } },
          data: rows.map((r) => ({ coords: ROUTES[r.stage_id], r,
            lineStyle: { color: colour(r), width: on(r) ? 4.5 : done(r) ? 2.5 : 1.5, opacity: done(r) ? 0.95 : 0.8 } })) },
        // start towns: hollow
        { type: 'scatter', coordinateSystem: 'geo', z: 4,
          data: rows.map((r) => ({ value: at(r, 0), r, symbolSize: 7,
            itemStyle: { color: t.surface, borderColor: colour(r), borderWidth: 1.6 } })) },
        // finish towns: filled, with the stage number
        { type: 'scatter', coordinateSystem: 'geo', z: 5,
          label: { show: true, distance: 5, fontFamily: t.mono, fontSize: 13, textBorderColor: t.surface, textBorderWidth: 3 },
          data: rows.map((r) => ({ value: at(r, 1), r, symbolSize: on(r) ? 13 : 9,
            itemStyle: { color: colour(r), borderColor: on(r) ? t.ink : t.surface, borderWidth: on(r) ? 2 : 1 },
            label: { formatter: `${r.stage_id}`, color: done(r) ? t.ink : t.muted, fontWeight: on(r) ? 700 : 400,
              position: LABEL_AT[r.stage_id] ?? (at(r, 1)[0] < at(r, 0)[0] ? 'left' : 'right') } })) },
        // the day that mattered most for the winner
        { type: 'scatter', coordinateSystem: 'geo', z: 6, silent: true, symbol: 'diamond', symbolSize: 12, symbolOffset: [0, -15],
          itemStyle: { color: t.jaune, borderColor: t.ink, borderWidth: 1 }, data: marks ? [{ value: at(race.decisive, 1) }] : [] },
        // the longest stage (replay only)
        { type: 'scatter', coordinateSystem: 'geo', z: 6, silent: true, symbol: 'triangle', symbolSize: 11, symbolOffset: [0, -15],
          itemStyle: { color: t.ink, borderColor: t.surface, borderWidth: 1 }, data: state.replay && marks ? [{ value: at(race.longest, 1) }] : [] },
      ],
    }
  }, { height: mapHeight(wide), onClick: (e) => { const r = e.data?.r; if (r) onPick(r.stage_id) } })
}
const mapHeight = (wide) => Math.max(320, Math.min(540, Math.round(wide * 0.87)))

// ---------- Rider heads for the replay (photos: Wikimedia Commons, credits in the README) ----------
// Built by tools/faces.py from 240 px thumbnails; one 52 px round PNG per rider who was ever in the first five overall.
const FACES = {
  "Tadej Pogacar": 'data:image/png;base64,',
  "Jonas Vingegaard": 'data:image/png;base64,',
  "Kévin Vauquelin": 'data:image/png;base64,',
  "Florian Lipowitz": 'data:image/png;base64,',
  "Oscar Onley": 'data:image/png;base64,',
  "Remco Evenepoel": 'data:image/png;base64,',
  "Mathieu Van Der Poel": 'data:image/png;base64,',
  "Matteo Jorgenson": 'data:image/png;base64,',
  "Primoz Roglic": 'data:image/png;base64,',
  "Félix Gall": 'data:image/png;base64,',
  "Ben Healy": 'data:image/png;base64,',
  "Enric Mas": 'data:image/png;base64,',
  "Jasper Philipsen": 'data:image/png;base64,',
  "Anthony Turgis": 'data:image/png;base64,',
  "Biniam Girmay": 'data:image/png;base64,',
  "Soren Waerenskjold": 'data:image/png;base64,',
  "Matteo Trentin": 'data:image/png;base64,',
}

// ---------- The race replayed stage by stage, one stage up close, the Mountain stages ----------
// Overall standing after every stage, for every rider who was in the first five at least once.
const runSql = `WITH run AS (
  SELECT p.stage_id, p.rider_key, p.gap_to_leader::int AS gap,
         ROW_NUMBER() OVER (PARTITION BY p.stage_id ORDER BY p.gc_rank, f.stage_rank, p.rider_key)::int AS place   -- riders level on time: the better stage place first
  FROM v_gc_progress p
  JOIN dim_stage s ON s.stage_id = p.stage_id
  LEFT JOIN fact_results f ON f.rider_key = p.rider_key AND f.stage_key = s.stage_key
), top AS (
  SELECT DISTINCT rider_key FROM run WHERE place <= 5
)
SELECT r.stage_id, r.rider_key, d.rider_name, r.gap, r.place
FROM run r
JOIN top USING (rider_key)
JOIN dim_rider d USING (rider_key)
ORDER BY r.stage_id, r.place;`
const fieldSql = `SELECT s.stage_id, COUNT(*)::int AS riders   -- riders with a result on the stage
FROM fact_results f
JOIN dim_stage s USING (stage_key)
GROUP BY s.stage_id
ORDER BY s.stage_id;`

// A rider on a bike, drawn as lines, for the head of each line.
const BIKE = 'path://M1.5,12a3.5,3.5 0 1,0 7,0a3.5,3.5 0 1,0 -7,0M15.5,12a3.5,3.5 0 1,0 7,0a3.5,3.5 0 1,0 -7,0M5,12L10,6L17,6L19,12M10,6L13,12L5,12M13,12L17,6M10,5L15,2.5L17.5,5.5M15.5,1.2a1.4,1.4 0 1,0 2.8,0a1.4,1.4 0 1,0 -2.8,0'
const STEP = 900   // milliseconds per stage
const triangle = () => h('i', { style: 'display:inline-block;width:0;height:0;margin:0 4px 1px 2px;border-left:5px solid transparent;border-right:5px solid transparent;border-bottom:9px solid var(--ink)' })

function replayOption(race, state, run, field, size) {
  const last = race.rows.at(-1).stage_id, champion = S.finishers[0].rider_key
  const gaps = new Map()
  for (const r of run) { if (!gaps.has(r.rider_key)) gaps.set(r.rider_key, new Map()); gaps.get(r.rider_key).set(r.stage_id, r.gap) }
  const surname = (name) => name.split(' ').slice(1).join(' ') || name
  const tick = (max) => [10, 30, 60, 120, 300, 600].find((s) => max / s <= 6) ?? 1200
  return (t) => {
    const n = state.n, { width, height } = size()
    const narrow = width < 520
    const top = run.filter((r) => r.stage_id === n && r.place <= 5)
    const lines = top.map((r) => ({ r, pts: [[0, 0], ...[...gaps.get(r.rider_key)].filter(([id]) => id <= n).sort((a, b) => a[0] - b[0])] }))   // everyone starts level
    const most = Math.max(10, ...lines.flatMap((l) => l.pts.map((p) => p[1])))
    const by = tick(most)
    const counts = field.filter((f) => f.stage_id <= n).map((f) => [f.stage_id, f.riders])
    const low = Math.floor((counts.at(-1)[1] - 1) / 10) * 10, high = Math.ceil(counts[0][1] / 10) * 10
    const ax = axisStyle(t)
    const g1h = 78, g0top = 48, g1top = height - 38 - g1h, g0h = g1top - 66 - g0top
    const right = narrow ? 96 : 138
    // stage k fills the slot from k - 1 to k, so the slope inside a slot is what that stage did; its number sits in the middle of the slot
    const span = Math.max(2, n), slot = (width - 62 - right) / span
    const xAxis = (gridIndex, show) => ({ type: 'value', gridIndex, min: 0, max: span, interval: 1, ...ax, splitLine: { show: false }, axisTick: { show: false },
      axisLabel: { ...ax.axisLabel, show, padding: [0, slot, 0, 0], formatter: (v) => (v === 0 || (slot < 20 && v % 2 === 0) ? '' : `${v}`) }, ...(show ? { name: 'Stage', nameLocation: 'middle', nameGap: 24, nameTextStyle: { color: t.muted } } : {}) })
    const head = { fontSize: 13, fontWeight: 600, color: t.ink, fontFamily: t.font }
    const move = { animationDurationUpdate: STEP - 60, animationEasingUpdate: 'linear' }
    const mark = (id, text) => ({ xAxis: id, label: { formatter: text } })
    // two riders close together: the lower one carries the photo under the bike, so the photos do not cover each other
    const deepest = Math.ceil(most / by) * by, px = (l) => (l.pts.at(-1)[1] / deepest) * g0h, under = new Set()
    ;[...lines].sort((a, b) => px(a) - px(b)).forEach((l, i, all) => {
      const gap = i ? px(l) - px(all[i - 1]) : 99, room = all[i + 1] ? px(all[i + 1]) - px(l) : 99
      if (gap > 4 && gap < 28 && room > 52 && !under.has(all[i - 1])) under.add(l)
    })
    // names closer than one text line are pushed down, top to bottom
    const drop = new Map()
    ;[...lines].sort((a, b) => px(a) - px(b)).reduce((floor, l) => { const y = Math.max(px(l), floor); drop.set(l, y - px(l)); return y + 15 }, -99)
    return {
      ...baseOpt(t), legend: { show: false },
      title: [{ text: 'Where the gaps opened: top 5, time behind the leader', left: 0, top: 0, textStyle: head }, { text: 'Riders finishing the stage', left: 0, top: g1top - 28, textStyle: head }],
      grid: [{ left: 62, right, top: g0top, height: g0h }, { left: 62, right, top: g1top, height: g1h }],
      axisPointer: { link: [{ xAxisIndex: 'all' }] },
      tooltip: { ...baseOpt(t).tooltip, trigger: 'axis', axisPointer: { type: 'line', snap: true, lineStyle: { color: t.axis } },
        formatter: (list) => {
          const id = Math.round(list[0].axisValue), r = race.get(id)
          if (!r) return ''
          const riders = list.filter((x) => x.seriesId?.startsWith('r')).sort((a, b) => a.value[1] - b.value[1])
          const f = field.find((x) => x.stage_id === id)
          return `<b>After stage ${id}</b> · ${arrow(r)}<br>${riders.map((x) => `${x.seriesName} <b style="float:right;margin-left:16px">${x.value[1] ? fmtGap(x.value[1]) : 'leader'}</b>`).join('<br>')}<br><span style="opacity:.75">${f.riders} riders finished. Click to open the stage.</span>`
        } },
      xAxis: [xAxis(0, false), xAxis(1, true)],
      yAxis: [
        { type: 'value', gridIndex: 0, inverse: true, min: 0, max: Math.ceil(most / by) * by, interval: by, ...ax, axisLabel: { ...ax.axisLabel, formatter: (v) => (v ? fmtGap(v) : 'Leader') } },
        { type: 'value', gridIndex: 1, min: low, max: high, interval: (high - low) / 2, ...ax },
      ],
      series: [
        // one slot per stage in the colour of its type: a light wash behind the lines and a solid strip under them
        { id: 'slots', type: 'custom', silent: true, z: 1, tooltip: { show: false }, ...move,
          data: race.rows.filter((r) => r.stage_id <= n).map((r) => ({ name: `s${r.stage_id}`, value: [r.stage_id, TERRAIN.indexOf(r.terrain)] })),
          renderItem: (p, api) => {
            const a = api.coord([api.value(0) - 1, 0])[0], b = api.coord([api.value(0), 0])[0], g = p.coordSys, fill = t.s[api.value(1)]
            const rect = (y, height, opacity) => ({ type: 'rect', transition: ['shape'], shape: { x: a, y, width: Math.max(1, b - a - 2), height }, style: { fill, opacity } })
            return { type: 'group', children: [rect(g.y, g.height, 0.1), rect(g.y + g.height + 5, 8, 1)] }
          } },
        ...lines.map(({ r, pts }) => {
          const me = r.rider_key === champion
          return { id: `r${r.rider_key}`, name: r.rider_name, type: 'line', data: pts, showSymbol: false, z: me ? 4 : 3, ...move,
            lineStyle: { color: me ? t.ink : t.ink2, width: me ? 3 : 1.4, opacity: me ? 1 : 0.6 }, itemStyle: { color: me ? t.ink : t.ink2 },
            emphasis: { focus: 'series', lineStyle: { width: me ? 3 : 2.5, opacity: 1 } } }
        }),
        // one bike per rider at the head of each line; the two marked stages hang on this series
        { id: 'heads', type: 'scatter', symbol: BIKE, symbolSize: [24, 17], symbolOffset: [9, -8], z: 6, ...move, tooltip: { show: false }, silent: true,
          itemStyle: { color: 'transparent', borderColor: t.ink, borderWidth: 1.3 },
          label: { show: true, position: 'right', distance: 6, fontFamily: t.font, fontSize: 12.5, color: t.ink2, formatter: (x) => x.name },
          data: lines.map((l) => ({ id: `h${l.r.rider_key}`, name: surname(l.r.rider_name), value: l.pts.at(-1),
            label: { offset: [0, drop.get(l)], ...(l.r.rider_key === champion ? { color: t.ink, fontWeight: 700 } : {}) } })),
          markLine: n < last ? { data: [] } : { silent: true, symbol: 'none', animation: false, lineStyle: { color: t.ink2, type: [4, 3], width: 1 },
            label: { position: 'start', distance: 4, color: t.ink, fontFamily: t.font, fontSize: 12 },
            data: [mark(race.decisive.stage_id, 'Key stage'), mark(race.longest.stage_id, 'Longest')] } },
        // the rider's photo as the head of the bike rider; a rider without a photo keeps the drawn head
        { id: 'faces', type: 'scatter', symbolSize: 24, symbolOffset: [15, -25], z: 7, ...move, tooltip: { show: false }, silent: true,
          data: [...lines].reverse().filter(({ r }) => FACES[r.rider_name]).map((l) => ({ id: `f${l.r.rider_key}`, value: l.pts.at(-1), symbol: `image://${FACES[l.r.rider_name]}`,
            ...(under.has(l) ? { symbolOffset: [15, 14] } : {}) })) },
        { id: 'field', name: 'Riders', type: 'line', xAxisIndex: 1, yAxisIndex: 1, data: counts, showSymbol: false, z: 3, ...move, lineStyle: { color: t.ink2, width: 2 }, itemStyle: { color: t.ink2 } },
        { id: 'fieldHead', type: 'scatter', xAxisIndex: 1, yAxisIndex: 1, symbolSize: 8, z: 4, ...move, silent: true, tooltip: { show: false },
          itemStyle: { color: t.ink2, borderColor: t.surface, borderWidth: 2 },
          label: { show: true, position: 'right', distance: 6, fontFamily: t.mono, fontSize: 12.5, color: t.ink },
          data: [{ id: 'now', name: 'now', value: counts.at(-1), label: { formatter: `${counts.at(-1)[1]}` } }] },
      ],
    }
  }
}

async function replayPanel(root, race, onOpen) {
  const run = await q(runSql), field = await q(fieldSql)
  const first = race.rows[0].stage_id, last = race.rows.at(-1).stage_id
  const still = matchMedia('(prefers-reduced-motion: reduce)').matches
  const state = { n: still ? last : first, replay: true }
  const p = panel(root, { title: 'The race, stage by stage', tag: 'E15', sql: runSql,
    note: 'The race replayed one stage at a time: the map follows the route, the top chart shows how far the top five overall sit behind the leader, and the bottom chart counts the riders still finishing.' })
  const stacked = root.clientWidth <= 900
  const wide = stacked ? root.clientWidth - 30 : root.clientWidth * 0.42
  const height = stacked ? 430 : mapHeight(wide)
  let timer = null
  const pick = (id) => { stop(); onOpen(id) }
  const map = routeMap(race, state, pick, wide)
  const option = replayOption(race, state, run, field, () => ({ width: line.clientWidth || 600, height }))
  const line = chart(option, { height })
  const btn = h('button', { class: 'btn', style: 'min-width:86px', onclick: () => (timer ? stop() : play()) })
  const slider = h('input', { type: 'range', min: first, max: last, step: 1, 'aria-label': 'Stage', style: 'flex:1 1 160px;max-width:360px', oninput: (e) => { const n = e.target.value; stop(); set(n) } })
  const caption = h('div', { class: 'row', style: 'gap:6px 10px;margin:0 0 10px;min-height:26px' })
  const legend = h('div', { style: 'display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;color:var(--ink2);margin:6px 0 0' })
  const draw = () => {
    const r = race.get(state.n)
    slider.value = state.n
    btn.textContent = timer ? '❚❚ Pause' : state.n >= last ? '↻ Replay' : '▶ Play'
    caption.replaceChildren(h('b', {}, `Stage ${r.stage_id} of ${race.rows.length}`), terrain(r.terrain), h('span', {}, `${day(r.stage_date)} · ${arrow(r)} · ${fmtNum(r.km, 1)} km`))
    legend.replaceChildren(...TERRAIN.map((type) => legendItem(swatch(terrainVar(type)), type)),
      ...(state.n >= last ? [legendItem(diamond(), 'key'), legendItem(triangle(), 'longest')] : []))
  }
  const set = (n) => {
    state.n = Math.min(last, Math.max(first, Number(n)))
    draw()
    redraw(map)
    // merged by series id, so every line and bike moves on from where it stood
    echarts.getInstanceByDom(line)?.setOption(option(tokens()), { replaceMerge: ['series'] })
  }
  function stop() { clearInterval(timer); timer = null; draw() }
  function play() {
    if (state.n >= last) set(first)
    timer = setInterval(() => {
      if (!p.el.isConnected) return clearInterval(timer)
      if (state.n >= last) return stop()
      set(state.n + 1)
      if (state.n >= last) stop()
    }, STEP)
    draw()
  }
  // a click anywhere above a stage number opens that stage
  line.addEventListener('click', (e) => {
    const inst = echarts.getInstanceByDom(line)
    if (!inst) return
    const box = line.getBoundingClientRect(), at = [e.clientX - box.left, e.clientY - box.top]
    if (!inst.containPixel({ gridIndex: 0 }, at) && !inst.containPixel({ gridIndex: 1 }, at)) return
    const id = Math.max(first, Math.ceil(inst.convertFromPixel({ gridIndex: 0 }, at)[0]))
    if (id >= first && id <= state.n) pick(id)
  })
  p.controls(btn, slider)
  p.body.append(caption,
    h('div', { style: 'display:flex;flex-wrap:wrap;gap:16px 20px;align-items:flex-start' },
      h('div', { style: 'flex:4 1 380px;min-width:0' },
        h('div', { style: `max-width:${Math.round(mapHeight(wide) / 0.87)}px;border:1px solid var(--line);border-radius:6px;overflow:hidden` }, map), legend),
      h('div', { style: 'flex:6 1 440px;min-width:0' }, line)),
    foot('Darker ground is higher. Click a stage to open it below.'),
    sources(['routes', 'cyclingstage.com', 'https://www.cyclingstage.com/tour-de-france-2025-route/'], ['heights', 'Terrain Tiles', 'https://registry.opendata.aws/terrain-tiles/'], ['photos', 'Wikimedia Commons', 'https://commons.wikimedia.org/']))
  draw()
  if (!still) setTimeout(() => { if (p.el.isConnected && !timer && state.n === first) play() }, 700)
}

// ---------- A stage in focus (E2): the first ten of one stage, riders or teams ----------
const riderTopSql = (id) => `SELECT f.stage_rank::int AS place, r.rider_key, r.rider_name, r.rider_country_code AS nat, t.team_key, t.team_name,
       f.adjusted_time::int AS adjusted_time,
       (f.adjusted_time - MIN(f.adjusted_time) FILTER (WHERE f.stage_rank = 1) OVER ())::int AS gap,   -- behind the stage winner
       g.gc_rank::int AS rank_after, (b.gc_rank - g.gc_rank)::int AS rank_move
FROM fact_results f
JOIN dim_stage s USING (stage_key)
JOIN dim_rider r USING (rider_key)
JOIN dim_team t USING (team_key)
LEFT JOIN v_gc_progress g ON g.rider_key = f.rider_key AND g.stage_id = s.stage_id
LEFT JOIN v_gc_progress b ON b.rider_key = f.rider_key AND b.stage_id = s.stage_id - 1
WHERE s.stage_id = ${Number(id)} AND f.stage_rank <= 10
ORDER BY f.stage_rank;`

const teamTopSql = (id) => `WITH picked AS (   -- each team's three fastest riders on every stage so far (the Best Team rule)
  SELECT f.team_key, s.stage_id, f.finish_time,
         ROW_NUMBER() OVER (PARTITION BY f.team_key, f.stage_key ORDER BY f.finish_time, f.stage_rank, f.rider_key) AS rn
  FROM fact_results f
  JOIN dim_stage s USING (stage_key)
  WHERE s.stage_id <= ${Number(id)}
), totals AS (   -- team time on this stage, after it, and after the stage before it
  SELECT team_key,
         SUM(finish_time) FILTER (WHERE stage_id = ${Number(id)}) AS t_day,
         SUM(finish_time) AS t_after,
         SUM(finish_time) FILTER (WHERE stage_id < ${Number(id)}) AS t_before
  FROM picked WHERE rn <= 3
  GROUP BY team_key
), ranks AS (
  SELECT team_key, t_day,
         RANK() OVER (ORDER BY t_day)::int AS place,
         RANK() OVER (ORDER BY t_after)::int AS rank_after,
         CASE WHEN t_before IS NOT NULL THEN RANK() OVER (ORDER BY t_before)::int END AS rank_before
  FROM totals
)
SELECT k.place, t.team_key, t.team_name, t.team_country_code AS nat,
       k.t_day::int AS team_time, (k.t_day - MIN(k.t_day) OVER ())::int AS gap,
       k.rank_after, (k.rank_before - k.rank_after)::int AS rank_move
FROM ranks k
JOIN dim_team t USING (team_key)
ORDER BY k.place, t.team_name
LIMIT 10;`

const banner = (r) => h('div', { style: 'margin:2px 0 12px' },
  kv([[`${r.stage_id}`, 'Stage'], [day(r.stage_date), 'Date'], [arrow(r), 'Start → finish'], [`${fmtNum(r.km, 1)} km`, 'Distance'], [terrain(r.terrain), 'Stage type']]))

async function topTen(id, mode, type) {
  const teams = mode === 'teams'
  const sql = teams ? teamTopSql(id) : riderTopSql(id)
  const rows = await q(sql)
  const most = Math.max(1, ...rows.map((r) => r.gap))
  const time = teams ? 'team_time' : 'adjusted_time'
  const gapCol = { k: 'gap', l: teams ? 'Team time, gap to the best team' : 'Adjusted time, gap to the winner',
    hint: teams ? 'The three fastest riders of the team on this stage, finish time without bonuses. First row: the time. Other rows: time behind it.' : 'Finish time minus bonus seconds plus penalties. First row: the time. Other rows: time behind the stage winner.',
    f: (v, r) => barCell(Math.max(0, v), most, r.place === 1 ? fmtTime(r[time]) : fmtGap(v), terrainVar(type)) }
  const nat = { k: 'nat', l: teams ? 'Country' : 'Nation', f: (v) => natLink(v) }
  const after = { k: 'rank_after', l: 'Overall after', n: 1, hint: `Place in the overall ${teams ? 'team ' : ''}ranking after this stage. ▲▼ places gained or lost that day.`, f: (v, r) => (v == null ? '' : [v, move(r.rank_move)]) }
  const cols = teams ? [{ k: 'place', l: 'Place', n: 1 }, teamCol(), gapCol, nat, after] : [{ k: 'place', l: 'Place', n: 1 }, riderCol(), gapCol, teamCol(), nat, after]
  return { sql, node: table({ rows, cols }) }
}

async function focusE(root, race) {
  let id = race.decisive.stage_id, mode = 'riders', type = 'All'
  const p = panel(root, { title: 'A stage in focus', tag: 'E2 · E11 · E15', sql: '',
    note: `One stage up close: the first ten riders and their time behind the stage winner; switch to Teams to compare the squads that day. It opens on stage ${race.decisive.stage_id}, where ${S.finishers[0].rider_name} gained the most time on ${S.finishers[1].rider_name}.` })
  // the stages worth a second look, each a shortcut
  const go = (r) => h('button', { class: 'lnk', onclick: () => set(r.stage_id) }, `Stage ${r.stage_id}`)
  const special = note('Special attention: ', 'longest stage ', go(race.longest), ` (${fmtNum(race.longest.km, 1)} km) · key stage for the winner `, go(race.decisive),
    ' · time trials ', ...race.rows.filter((r) => r.terrain === 'ITT').flatMap((r, i) => [i ? ' and ' : '', go(r)]))
  const typeSlot = h('span', {}), pickSlot = h('span', {}), head = h('div', {}), slot = h('div', {})
  const count = (t) => race.rows.filter((r) => r.terrain === t).length
  const listed = () => race.rows.filter((r) => type === 'All' || r.terrain === type)
  // the type buttons and the stage menu are rebuilt together, so the menu only ever offers stages of the chosen type
  const drawPick = () => {
    typeSlot.replaceChildren(seg([['All', `All (${race.rows.length})`], ...TERRAIN.map((t) => [t, `${t} (${count(t)})`])], type, (v) => {
      type = v
      if (!listed().some((r) => r.stage_id === id)) id = listed()[0].stage_id
      drawPick()
      draw()
    }))
    pickSlot.replaceChildren(select(listed().map((r) => [r.stage_id, `Stage ${r.stage_id} · ${arrow(r)}`]), id, (v) => { id = Number(v); draw() }, { 'aria-label': 'Stage' }))
  }
  p.controls(typeSlot, pickSlot, seg([['riders', 'Riders'], ['teams', 'Teams']], mode, (m) => { mode = m; draw() }))
  p.body.append(special, head, slot)
  const draw = async () => {
    const r = race.get(id), top = await topTen(id, mode, r.terrain)
    p.sql = top.sql
    head.replaceChildren(banner(r))
    slot.replaceChildren(top.node)
  }
  const set = async (next, scroll) => {
    id = Number(next)
    if (type !== 'All' && race.get(id).terrain !== type) type = 'All'
    drawPick()
    await draw()
    if (scroll) p.el.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }
  drawPick()
  await draw()
  return { set, el: p.el }
}

// The same stage card in the side drawer.
async function stageViewE(id, title, body) {
  const race = await loadRace(), r = race.get(id)
  title.textContent = `Stage ${r.stage_id}: ${arrow(r)}`
  const slot = h('div', {})
  const show = async (m) => { const top = await topTen(id, m, r.terrain); sweep(); slot.replaceChildren(top.node, h('div', { style: 'height:8px' }), sqlShow(top.sql)) }
  body.append(banner(r), seg([['riders', 'Riders'], ['teams', 'Teams']], 'riders', show), h('div', { style: 'height:8px' }), slot)
  await show('riders')
}

// ---------- All stages (E11, E15): one row per stage, longest first ----------
async function stageListPanel(root, focus) {
  const sql = `SELECT s.stage_id, s.stage_date::text AS stage_date, s.terrain, s.start_location, s.finish_location,
       s.distance_km::float8 AS km, r.rider_key, r.rider_name AS winner, t.team_key, t.team_name
FROM dim_stage s
JOIN fact_results f ON f.stage_key = s.stage_key AND f.is_win = 1   -- the stage winner
JOIN dim_rider r ON r.rider_key = f.rider_key
JOIN dim_team t ON t.team_key = f.team_key
ORDER BY s.distance_km DESC;`
  const rows = await q(sql)
  const count = (t) => rows.filter((r) => r.terrain === t).length
  const p = panel(root, { title: `All ${rows.length} stages`, tag: 'E11 · E15', sql,
    note: `Every stage with its date, route, type, distance and winner, longest first: stage ${rows[0].stage_id} is the longest at ${fmtNum(rows[0].km, 1)} km. The ${count('ITT')} time trials are stages ${rows.filter((r) => r.terrain === 'ITT').map((r) => r.stage_id).sort((a, b) => a - b).join(' and ')}; click Type to group them. Click a row to open that stage above.` })
  p.body.append(table({ rows, onRow: (r) => focus.set(r.stage_id, true), hit: (r) => r === rows[0], cols: [
    { k: 'stage_id', l: 'Stage', n: 1 },
    { k: 'stage_date', l: 'Date', f: (v) => h('span', { style: 'white-space:nowrap' }, day(v)) },
    { k: 'start_location', l: 'Start → finish', f: (v, r) => arrow(r) },
    { k: 'terrain', l: 'Type', f: (v) => terrain(v) },
    { k: 'km', l: 'Distance', n: 1, f: (v) => `${fmtNum(v, 1)} km` },
    { ...riderCol('winner'), l: 'Winner' },
    teamCol(),
  ] }))
}

// ---------- Mountain stages (E5): podiums and mean gap, with the daily gaps behind them ----------
async function mountainPanel(root, focus, span = 7) {
  const sql = `SELECT r.rider_key, r.rider_name,
       SUM(f.is_podium)::int AS podiums,                  -- top-three finishes on Mountain stages
       ROUND(AVG(f.gap_to_winner))::int AS mean_gap,      -- mean gap to the stage winner, seconds
${S.mountain.map((id) => `       MAX(f.gap_to_winner) FILTER (WHERE s.stage_id = ${id})::int AS gap_${id}, MAX(f.stage_rank) FILTER (WHERE s.stage_id = ${id})::int AS place_${id}`).join(',\n')}
FROM fact_results f
JOIN dim_stage s USING (stage_key)
JOIN dim_rider r USING (rider_key)
WHERE s.terrain = 'Mountain' AND r.race_status = 'Finished'
GROUP BY r.rider_key, r.rider_name
ORDER BY podiums DESC, mean_gap;`
  const rows = await q(sql)
  const p = panel(root, { title: 'Mountain stages', tag: 'E5', span, sql,
    note: `Who climbed best: top-three finishes and average time behind the stage winner on the ${S.mountain.length} Mountain stages, with the gap on each one.` })
  const most = Math.max(...rows.map((r) => r.podiums))
  const cell = (id) => (v, r) => (r[`place_${id}`] <= 3
    ? h('span', { title: `${ord(r[`place_${id}`])} place`, style: 'font-weight:700;padding:1px 4px;border-radius:3px;background:color-mix(in srgb, var(--jaune) 28%, transparent)' }, fmtGap(v))
    : fmtGap(v))
  p.body.append(table({ rows, limit: 10, cols: [
    riderCol(),
    { k: 'podiums', l: `Podiums in ${S.mountain.length}`, hint: 'Top-three finishes on the Mountain stages', f: (v) => barCell(v, most, v, terrainVar('Mountain')) },
    { k: 'mean_gap', l: 'Mean gap', n: 1, hint: 'Average time behind the stage winner on the Mountain stages, finish time', f: (v) => fmtGap(v) },
    ...S.mountain.map((id) => ({ k: `gap_${id}`, l: `S${id}`, n: 1, hint: `Stage ${id}: ${S.stages.find((s) => s.stage_id === id).route}`, f: cell(id) })),
  ] }), foot('S columns: gap to the stage winner. Tinted: podium.'))
}

// ---------- Speed by stage type (E6): km/h = kilometres ridden / hours taken ----------
const PACE_KEYS = ['flat', 'hilly', 'mountain', 'itt']   // same order as TERRAIN
const paceSql = (level) => {
  const who = level === 'riders' ? 'r.rider_key AS key, r.rider_name AS name,' : level === 'teams' ? 't.team_key AS key, t.team_name AS name,' : `0 AS key, 'All riders' AS name,`
  const group = level === 'riders' ? '\n  GROUP BY r.rider_key, r.rider_name' : level === 'teams' ? '\n  GROUP BY t.team_key, t.team_name' : ''
  const ratio = (where) => `SUM(s.distance_km) FILTER (WHERE ${where}) / SUM(f.finish_time) FILTER (WHERE ${where}) * 3600`
  return `WITH speed AS (   -- km/h = kilometres ridden / hours taken, added up over the stages of one type
  SELECT ${who}
         ${ratio(`s.terrain = 'Flat'`)} AS flat,
         ${ratio(`s.terrain = 'Hilly'`)} AS hilly,
         ${ratio(`s.terrain = 'Mountain'`)} AS mountain,
         ${ratio(`s.terrain = 'ITT'`)} AS itt,
         ${ratio(`s.terrain IN ('Flat', 'Hilly')`)} AS flat_hilly,
         -- seconds per rider on all stages of one type
         SUM(f.finish_time) FILTER (WHERE s.terrain = 'Flat') / COUNT(DISTINCT r.rider_key) AS flat_time,
         SUM(f.finish_time) FILTER (WHERE s.terrain = 'Hilly') / COUNT(DISTINCT r.rider_key) AS hilly_time,
         SUM(f.finish_time) FILTER (WHERE s.terrain = 'Mountain') / COUNT(DISTINCT r.rider_key) AS mountain_time,
         SUM(f.finish_time) FILTER (WHERE s.terrain = 'ITT') / COUNT(DISTINCT r.rider_key) AS itt_time
  FROM fact_results f
  JOIN dim_stage s USING (stage_key)
  JOIN dim_rider r USING (rider_key)
  JOIN dim_team t ON t.team_key = f.team_key
  WHERE r.race_status = 'Finished'   -- finishers only, so everyone is measured on the same stages${group}
)
SELECT key, name, flat::float8 AS flat, hilly::float8 AS hilly, mountain::float8 AS mountain, itt::float8 AS itt,
       flat_hilly::float8 AS flat_hilly,
       flat_time::float8 AS flat_time, hilly_time::float8 AS hilly_time, mountain_time::float8 AS mountain_time, itt_time::float8 AS itt_time,
       RANK() OVER (ORDER BY flat_time + hilly_time + mountain_time + itt_time)::int AS place   -- least total time first
FROM speed
ORDER BY place, name;`
}
async function pacePanel(root) {
  const [field] = await q(paceSql('field'))
  const data = { riders: await q(paceSql('riders')), teams: await q(paceSql('teams')) }
  const first = S.finishers[0]
  const chosen = { riders: first.rider_key, teams: S.teams.find((t) => t.team_name === first.team_name).team_key }
  let level = 'riders'
  const label = (r) => (level === 'teams' ? shortTeam(r.name) : r.name)
  const current = () => data[level].find((r) => r.key === chosen[level])
  const ahead = (r, k) => (field[`${k}_time`] - r[`${k}_time`]) / 60   // minutes ahead of the average rider on all stages of one type
  const total = (r) => PACE_KEYS.reduce((sum, k) => sum + ahead(r, k), 0)
  const mins = (v) => `${v >= 0 ? '+' : '−'}${fmtNum(Math.abs(v), 0)} min`
  const all = () => (level === 'teams' ? 'All teams' : 'All riders')

  const p = panel(root, { title: 'Speed by stage type', tag: 'E6', sql: paceSql(level),
    note: 'Average speed on Flat, Hilly, Mountain and ITT stages for one rider or team against the field (left), and how many minutes each one gains or loses on the average rider by stage type (right).' })
  p.body.append(note(`Speed = total km ÷ total hours on the stages of one type, ${data.riders.length} finishers.`))
  const pickSlot = h('span', {}), leftHead = h('div', {}), rightHead = h('div', {})
  const left = h('div', { style: 'min-width:0' }), right = h('div', { style: 'min-width:0' })
  p.controls(seg([['riders', 'Riders'], ['teams', 'Teams']], level, (v) => { level = v; build() }), pickSlot)

  // Left: one row per stage type, the selection as a dot against all riders as a tick.
  const profile = () => chart((t) => {
    const me = current(), ax = axisStyle(t)
    const vals = [field, ...data[level]].flatMap((r) => PACE_KEYS.map((k) => r[k]))
    const lo = Math.floor(Math.min(...vals) / 4) * 4, hi = Math.ceil(Math.max(...vals) / 4) * 4
    const rich = Object.fromEntries(TERRAIN.map((_, i) => [`s${i}`, { width: 10, height: 10, borderRadius: 2, backgroundColor: t.s[i] }]))
    return {
      ...baseOpt(t),
      legend: { ...baseOpt(t).legend, selectedMode: false, data: [{ name: label(me), icon: 'circle' }, { name: all(), icon: 'rect' }] },
      grid: { left: 96, right: 110, top: 34, bottom: 46 },
      tooltip: { ...baseOpt(t).tooltip, trigger: 'axis', axisPointer: { type: 'shadow' },
        formatter: (x) => { const k = PACE_KEYS[x[0].dataIndex]; return `<b>${TERRAIN[x[0].dataIndex]}</b><br>${label(me)}: <b>${kmh(me[k])} km/h</b><br>${all()}: ${kmh(field[k])} km/h<br>Difference: ${signed(me[k] - field[k])} km/h` } },
      xAxis: { type: 'value', ...ax, min: lo, max: hi, interval: 4, name: 'Speed (km/h)', nameLocation: 'middle', nameGap: 28, nameTextStyle: { color: t.muted } },
      yAxis: [{ type: 'category', ...ax, inverse: true, data: TERRAIN, splitLine: { show: false }, name: 'Stage type', nameLocation: 'start', nameGap: 10, nameTextStyle: { color: t.muted, align: 'right' },
        axisLabel: { color: t.ink, fontSize: 13, rich, formatter: (v, i) => `{s${i}|} ${v}` } },
        // the values as a column on the right: speed, and the difference to all riders in brackets
        { type: 'category', inverse: true, position: 'right', axisLine: { show: false }, axisTick: { show: false }, name: `km/h (vs ${all().toLowerCase()})`, nameLocation: 'start', nameGap: 10, nameTextStyle: { color: t.muted, align: 'left' },
          data: PACE_KEYS.map((k) => `${kmh(me[k], 1)} (${signed(me[k] - field[k], 1)})`), axisLabel: { color: t.ink, fontFamily: t.mono, fontSize: 12 } }],
      series: [
        { type: 'custom', silent: true, z: 2, data: PACE_KEYS.map((k, i) => [field[k], me[k], i]),
          renderItem: (_, api) => {
            const a = api.coord([api.value(0), api.value(2)]), b = api.coord([api.value(1), api.value(2)])
            return { type: 'line', shape: { x1: a[0], y1: a[1], x2: b[0], y2: b[1] }, style: { stroke: t.axis, lineWidth: 2 } }
          } },
        { name: all(), type: 'scatter', z: 3, symbol: 'rect', symbolSize: [4, 20], itemStyle: { color: t.muted },
          data: PACE_KEYS.map((k, i) => [field[k], i]) },
        { name: label(me), type: 'scatter', z: 4, symbolSize: 13, itemStyle: { color: t.ink, borderColor: t.surface, borderWidth: 2 },
          data: PACE_KEYS.map((k, i) => [me[k], i]) },
      ],
    }
  }, { height: 250 })

  // Right: the five who keep most of their speed in the mountains, the three who keep least, and the selection.
  const shown = () => {
    const list = data[level], keep = new Set([...list.slice(0, 5), ...list.slice(-3), current()])
    const rows = []
    for (const r of list) {
      if (!keep.has(r)) continue
      if (rows.length && list.indexOf(r) - list.indexOf(rows.at(-1)) > 1) rows.push(null)   // a gap in the ranking
      rows.push(r)
    }
    return rows
  }
  const pickRow = (r) => { if (r && r.key !== chosen[level]) { chosen[level] = r.key; build() } }
  const ranking = () => {
    const rows = shown()
    return chart((t) => {
      const ax = axisStyle(t), list = data[level]
      // negative parts stack to the left of zero, positive parts to the right
      const reach = (r, sign) => PACE_KEYS.reduce((sum, k) => sum + Math.max(0, sign * ahead(r, k)), 0)
      const far = [-1, 1].map((sign) => Math.max(...list.map((r) => reach(r, sign)))), by = Math.max(...far) > 150 ? 60 : 30
      const lo = -Math.ceil(far[0] / by) * by, hi = Math.ceil(far[1] / by) * by
      const on = (r) => r && r.key === chosen[level]
      const who = level === 'teams' ? 'team (per rider)' : 'rider'
      return {
        ...baseOpt(t),
        legend: { ...baseOpt(t).legend, selectedMode: false, data: TERRAIN, top: 0 },
        grid: { left: 8, right: 168, top: 58, bottom: 46, containLabel: true },
        tooltip: { ...baseOpt(t).tooltip, trigger: 'axis', axisPointer: { type: 'shadow' },
          formatter: (x) => { const r = rows[x[0].dataIndex]; return r ? `<b>${label(r)}</b> · ${ord(r.place)} of ${list.length}<br>${PACE_KEYS.map((k, i) => `${TERRAIN[i]}: ${mins(ahead(r, k))}`).join('<br>')}<br>All stages: <b>${mins(total(r))}</b>` : '' } },
        xAxis: { type: 'value', ...ax, min: lo, max: hi, interval: by, name: `Minutes ahead of the average ${who}, by stage type`, nameLocation: 'middle', nameGap: 28, nameTextStyle: { color: t.muted },
          axisLabel: { ...ax.axisLabel, hideOverlap: true, formatter: (v) => (v > 0 ? `+${v}` : `${v}`.replace('-', '−')) } },
        yAxis: { type: 'category', ...ax, axisLine: { ...ax.axisLine, onZero: false }, inverse: true, triggerEvent: true, splitLine: { show: false }, axisLabel: { ...ax.axisLabel, width: 150, overflow: 'truncate' },
          name: `Rank of ${list.length}`, nameLocation: 'start', nameGap: 10, nameTextStyle: { color: t.muted, align: 'right' },
          data: rows.map((r, i) => (r ? { value: `${r.place}  ${label(r)}`, textStyle: { color: t.ink, fontFamily: t.font, fontSize: 13, fontWeight: on(r) ? 700 : 400 } } : { value: `…${' '.repeat(i)}`, textStyle: { color: t.muted } })) },
        series: [
          ...PACE_KEYS.map((k, i) => ({ name: TERRAIN[i], type: 'bar', stack: 'gain', barWidth: 14, cursor: 'pointer',
            itemStyle: { color: t.s[i], borderColor: t.surface, borderWidth: 1 },
            data: rows.map((r) => (r ? { value: ahead(r, k), r } : '-')) })),
          // the total at the end of each bar, with the Mountain part spelled out
          { type: 'scatter', silent: true, symbolSize: 0, z: 5, tooltip: { show: false },
            markLine: { silent: true, symbol: 'none', lineStyle: { color: t.muted, width: 2, type: 'solid' }, label: { color: t.ink2, fontSize: 12, position: 'start', formatter: `Average ${level === 'teams' ? 'team' : 'rider'}` }, data: [{ xAxis: 0 }] },
            label: { show: true, color: t.ink, fontFamily: t.mono, fontSize: 12, distance: 6 },
            data: rows.map((r, i) => { if (!r) return null
              // the Mountain share is only stated when the Mountain part and the total point the same way
              const m = ahead(r, 'mountain'), share = m * total(r) > 0 && Math.abs(m) <= Math.abs(total(r)) ? `, ${fmtNum(m / total(r) * 100, 0)}% Mountain` : ''
              return { value: [reach(r, 1), i], label: { position: 'right', formatter: `${mins(total(r))}${share}` } } }).filter(Boolean) },
        ],
      }
    }, { height: 108 + rows.length * 30, onClick: (e) => pickRow(e.data?.r ?? (e.componentType === 'yAxis' ? rows[e.dataIndex] ?? rows.find((r) => r && `${r.place}  ${label(r)}` === e.value) : null)) })
  }

  const build = () => {
    const me = current(), list = data[level]
    p.sql = paceSql(level)
    pickSlot.replaceChildren(select(list.map((r) => [r.key, `${r.place}. ${label(r)}`]), me.key, (v) => { chosen[level] = Number(v); build() }, { 'aria-label': level === 'teams' ? 'Team' : 'Rider' }))
    leftHead.replaceChildren(subhead(`${label(me)} against ${all().toLowerCase()}`))
    rightHead.replaceChildren(subhead('Where the time is won and lost'))
    sweep()
    left.replaceChildren(leftHead, profile())
    right.replaceChildren(rightHead, ranking())
  }
  p.body.append(h('div', { style: 'display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,420px),1fr));gap:12px 28px;align-items:start' }, left, right))
  build()
}

// ---------- Page order ----------
// 0 the course in one row of numbers, 1 the race replayed stage by stage, 2 one stage up close, picked from a menu narrowed by stage type (time trials under ITT), 3 speed by stage type, 4 the Mountain stages.
CFG.focus = 'gain'   // the key stage: where the final winner gained the most time on the runner-up

async function render(el) {
  const race = await loadRace()
  let focus
  statRow(el, race)
  await replayPanel(el, race, (id) => focus.set(id, true))
  focus = await focusE(el, race)
  await pacePanel(el)
  await mountainPanel(el, focus, 0)
  await stageListPanel(el, focus)
}

VIEWS.stage = stageViewE
export { stageViewE as stageView }
export default { id: 'stages', label: 'Stages', render }
